/**
 * Single source of truth for HTTP security headers.
 *
 * Consumers:
 *  - vite.config.ts (preview server headers, so E2E runs under the production CSP)
 *  - nginx/security-headers.conf (generated)
 *  - public/staticwebapp.config.json -> globalHeaders (generated)
 *
 * Usage:
 *   npm run headers            # regenerate the nginx snippet + SWA config
 *   npm run headers -- --check # exit 1 if generated files drifted (CI)
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath, pathToFileURL } from 'node:url'

export const CSP = [
  "default-src 'self'",
  // wasm-unsafe-eval: hash-wasm / meshoptimizer compile WebAssembly (no JS eval allowed).
  "script-src 'self' 'wasm-unsafe-eval'",
  "worker-src 'self'",
  // Tailwind/shadcn/Base UI set inline style attributes; no inline <script> is ever allowed.
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' data: blob:",
  "font-src 'self' data:",
  // blob: lets workers/loaders read object URLs for user-dropped files. The app never calls external hosts.
  "connect-src 'self' blob:",
  "manifest-src 'self'",
  "object-src 'none'",
  "base-uri 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
].join('; ')

/**
 * Headers safe on any transport. HSTS and COOP are added only where TLS is guaranteed (SWA):
 * browsers ignore COOP on plain HTTP and log a console error, which LAN Docker users would see.
 * Self-hosters behind an HTTPS proxy should add both at the proxy (see docs/deploy.md).
 */
export function securityHeaders(opts: { https?: boolean } = {}): Record<string, string> {
  const headers: Record<string, string> = {
    'Content-Security-Policy': CSP,
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
    'Cross-Origin-Resource-Policy': 'same-origin',
    'X-Frame-Options': 'DENY',
  }
  if (opts.https) {
    headers['Cross-Origin-Opener-Policy'] = 'same-origin'
    headers['Strict-Transport-Security'] = 'max-age=63072000; includeSubDomains'
  }
  return headers
}

const root = fileURLToPath(new URL('..', import.meta.url))
const NGINX_SNIPPET = `${root}nginx/security-headers.conf`
const SWA_CONFIG = `${root}public/staticwebapp.config.json`

export function renderNginxSnippet(): string {
  const lines = Object.entries(securityHeaders()).map(
    ([name, value]) => `add_header ${name} "${value}" always;`,
  )
  return [
    '# GENERATED by scripts/headers.ts — do not edit by hand (run `npm run headers`).',
    '# TLS is terminated by your reverse proxy; add HSTS there if you serve HTTPS.',
    ...lines,
    '',
  ].join('\n')
}

type SwaConfig = Record<string, unknown> & { globalHeaders?: Record<string, string> }

export function renderSwaConfig(current: SwaConfig): string {
  const next: SwaConfig = {
    ...current,
    globalHeaders: {
      // index.html and other non-hashed files must revalidate; /assets/* overrides this via routes.
      'Cache-Control': 'no-cache',
      ...securityHeaders({ https: true }),
    },
  }
  return `${JSON.stringify(next, null, 2)}\n`
}

function readSwa(): SwaConfig {
  return JSON.parse(readFileSync(SWA_CONFIG, 'utf8')) as SwaConfig
}

function main(): void {
  const check = process.argv.includes('--check')
  const outputs: Array<[path: string, content: string]> = [
    [NGINX_SNIPPET, renderNginxSnippet()],
    [SWA_CONFIG, renderSwaConfig(readSwa())],
  ]
  let drift = false
  for (const [path, content] of outputs) {
    let existing = ''
    try {
      existing = readFileSync(path, 'utf8')
    } catch {
      existing = ''
    }
    if (existing === content) continue
    if (check) {
      console.error(`headers drift: ${path} is out of date (run \`npm run headers\`)`)
      drift = true
    } else {
      writeFileSync(path, content)
      console.log(`wrote ${path}`)
    }
  }
  if (drift) process.exit(1)
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main()
